use vstd::prelude::*;

verus! {

/// Spec-level predicate: every character is an ASCII digit.
spec fn all_digits(s: Seq<char>) -> bool {
    forall|i: int| 0 <= i < s.len() ==> ('0' <= s[i] && s[i] <= '9')
}

fn is_integer(text: &Vec<char>) -> (res: bool)
    ensures
        res == all_digits(text@),
{
    for &ch in text.iter()
        invariant
            // We've checked all positions before the current iterator position.
            forall|i: int| 0 <= i < text.iter().position() ==> ('0' <= text@[i] && text@[i] <= '9'),
    {
        if !matches!(ch, '0'..='9') {
            return false;
        }
    }
    true
}

} // verus!

